import assert from 'node:assert/strict';import fs from 'node:fs';import {performance} from 'node:perf_hooks';
import {current,fixture,oldFile,writeResults,worklet,html,out} from './fixtures.mjs';
const old=await fixture(oldFile('worklet.js'),'v041-refinement'),{Engine,DriveClass,PRESETS,defaultState,decodeSamples,sampleAt}=current,zones=decodeSamples(),tests=[],metrics={};
const test=(name,fn)=>{fn();tests.push(name);console.log('PASS',name);};
function make(id='motorik',extra={},C=Engine,sr=48000){const e=new C(sr);e.message({type:'samples',zones});const p=PRESETS.find(x=>x.id===id);e.configure({...defaultState(),preset:id,drumVolume:0,fx:{...p,reverb:0,wooze:0,crush:0},...extra});return e;}
function render(e,seconds,capture=false){const frames=Math.round(e.sr*seconds),l=new Float32Array(128),r=new Float32Array(128),data=capture?new Float64Array(frames):null;let sum=0,peak=0,delta=0,last=0;for(let n=0;n<frames;n+=128){const a=l.subarray(0,Math.min(128,frames-n)),b=r.subarray(0,a.length);e.process(a,b);for(let j=0;j<a.length;j++){assert.ok(Number.isFinite(a[j])&&Number.isFinite(b[j]));sum+=(a[j]*a[j]+b[j]*b[j])*.5;peak=Math.max(peak,Math.abs(a[j]),Math.abs(b[j]));delta=Math.max(delta,Math.abs(a[j]-last));last=a[j];if(data)data[n+j]=a[j];}}return{rms:Math.sqrt(sum/frames),peak,delta,data};}
const db=(a,b)=>20*Math.log10(Math.max(a,1e-15)/Math.max(b,1e-15));
function fft(input){const n=input.length,re=Float64Array.from(input),im=new Float64Array(n);for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)[re[i],re[j]]=[re[j],re[i]];}for(let size=2;size<=n;size*=2){const half=size/2;for(let a=0;a<n;a+=size)for(let j=0;j<half;j++){const c=Math.cos(-2*Math.PI*j/size),s=Math.sin(-2*Math.PI*j/size),k=a+j+half,r=re[k]*c-im[k]*s,m=re[k]*s+im[k]*c;re[k]=re[a+j]-r;im[k]=im[a+j]-m;re[a+j]+=r;im[a+j]+=m;}}return re.map((r,i)=>r*r+im[i]*im[i]);}
test('One CRUSH control ignores legacy zero LEVEL and stays audible across all twelve instruments',()=>{
 assert.equal(defaultState().crushLevel,undefined);assert.ok(!html.includes("slider(box,'crush level'"));metrics.crush=[];
 for(const p of PRESETS)for(const velocity of [.2,.8]){const levels=[];for(const crush of [0,.25,.5,.75,1]){const e=make(p.id,{crushLevel:0,fx:{...p,reverb:0,wooze:0,crush}});for(const n of [48,55,62,65])e.note(n,velocity,-1,'manual');render(e,.3);const o=render(e,.8);assert.ok(o.rms>1e-5,p.id+' silence');assert.ok(o.peak<.881);levels.push(o.rms);}const changes=levels.map(x=>db(x,levels[0]));metrics.crush.push({preset:p.id,velocity,relativeDB:changes});assert.ok(Math.max(...changes)<2.5);assert.ok(Math.min(...changes)>-12,JSON.stringify(metrics.crush.at(-1)));}
});
test('CRUSH zero is unchanged and high CRUSH retains the original quantized harmonic stem',()=>{
 metrics.crushStem=[];for(const crush of [0,.75,1]){const a=make('motorik',{fx:{attack:.008,release:1,reverb:0,wooze:0,crush}}),b=make('motorik',{fx:{attack:.008,release:1,reverb:0,wooze:0,crush}},old.Engine);for(const e of [a,b])e.note(60,.8,-1,'manual');const l=new Float32Array(1),r=new Float32Array(1),x=new Float32Array(1),y=new Float32Array(1);let difference=0;for(let i=0;i<24000;i++){a.process(l,r);b.process(x,y);assert.equal(a.heldL,b.heldL);assert.equal(a.crushPhase,b.crushPhase);assert.equal(a.crushWet,b.crushWet);assert.equal(a.crushGain,b.crushGain);difference+=Math.abs(l[0]-x[0]);if(crush===0)assert.equal(l[0],x[0]);}if(crush>0)assert.ok(difference>1);metrics.crushStem.push({crush,quantizerAndWetStemIdentical:true,comfortGain:a.crushComfort});}
});
test('Original sample bytes stay unchanged; sustained loop seams are continuous and one-shot playback is exact',()=>{
 metrics.sampleSeams=[];for(const z of zones){const fade=Math.min(Math.round(z.rate*.012),Math.floor((z.loopEnd-z.loopStart)/8));const at=p=>sampleAt({z,pos:p,ratio:1,weight:1},0,true);const epsilon=1e-5,newGap=Math.abs(at(z.loopEnd)-at(z.loopEnd-epsilon)),oldGap=Math.abs(z.data[z.loopStart]-z.data[z.loopEnd-1]);assert.ok(newGap<1e-5,z.id+' seam '+newGap);metrics.sampleSeams.push({id:z.id,sourceGap:oldGap,repairedEpsilonGap:newGap});for(const p of [0,z.loopStart,z.loopEnd-fade-2,z.loopEnd-.5,z.loopEnd+2]){const a={z,pos:p,ratio:1,weight:.6},b={...a};assert.equal(sampleAt(a,1.15,false),old.sampleAt(b,1.15,false));assert.equal(a.pos,b.pos);}}
});
test('Drum retriggers bridge existing tails instead of hard resetting the waveform, at both sample rates',()=>{
 metrics.retriggers=[];for(const sr of [44100,48000])for(const tempo of [80,120,180,220]){const jumps=[];for(const C of [old.Engine,Engine]){const e=make('motorik',{tempo,rhythm:4,drumVolume:.6},C,sr);e.message({type:'drums',on:true});const l=new Float32Array(1),r=new Float32Array(1);let previous=0,trigger=false,max=0;e.trace=t=>{if(t.kind==='drum'&&t.hits[0]&&t.frame>0)trigger=true;};for(let n=0;n<sr*2;n++){e.process(l,r);if(trigger){max=Math.max(max,Math.abs(l[0]-previous));trigger=false;}previous=l[0];}jumps.push(max);}assert.ok(jumps[1]<jumps[0]*.12,JSON.stringify({sr,tempo,jumps}));metrics.retriggers.push({sr,tempo,oldJump:jumps[0],newJump:jumps[1]});}
});
test('A BPM edit never jumps the current sample, musical phase, active note ids or scheduled event positions',()=>{
 metrics.tempoChanges=[];for(const sr of [44100,48000])for(const mode of ['drums','chord','arp','both','all']){const a=make('motorik',{drumVolume:mode==='drums'||mode==='all'?.6:0,arp:{...defaultState().arp,mode:mode==='drums'||mode==='all'?'both':mode}},Engine,sr),b=make('motorik',{drumVolume:mode==='drums'||mode==='all'?.6:0,arp:{...defaultState().arp,mode:mode==='drums'||mode==='all'?'both':mode}},Engine,sr);for(const e of [a,b])e.message({type:mode==='drums'?'drums':'sequence',on:true});render(a,.231);render(b,.231);
  const pos=[a.clock.tick,a.clock.phase,a.nextDrum,a.nextArp],voices=a.voices.map(v=>v.id);a.configure({...defaultState(),preset:'motorik',tempo:220,fx:{...a.target},drumVolume:a.drumVolume,arp:{...a.arp}});assert.deepEqual([a.clock.tick,a.clock.phase,a.nextDrum,a.nextArp],pos);assert.deepEqual(a.voices.map(v=>v.id),voices);const l=new Float32Array(1),r=new Float32Array(1),x=new Float32Array(1),y=new Float32Array(1);a.process(l,r);b.process(x,y);assert.equal(l[0],x[0]);assert.equal(r[0],y[0]);metrics.tempoChanges.push({sr,mode,firstSampleError:0});}
});
test('Rapid/gradual BPM changes preserve every drum and arp event, fractional swing and PAUSE/RESUME',()=>{
 metrics.tempoSoak=[];for(const sr of [44100,48000])for(const mode of ['drums','chord','arp','both','all']){const e=make('motorik',{drumVolume:mode==='drums'||mode==='all'?.6:0,tempo:40,swing:.8,arp:{...defaultState().arp,mode:mode==='drums'||mode==='all'?'both':mode,speed:3,length:.7}},Engine,sr);e.message({type:mode==='drums'?'drums':'sequence',on:true});const trace=[];e.trace=t=>trace.push([t.kind,t.tick]);let peak=0;for(let i=0;i<80;i++){const tempo=i<40?40+i*4.6:[40,220,75,198][i%4];const pos=e.clock.beat;e.configure({tempo});assert.equal(e.clock.beat,pos);peak=Math.max(peak,render(e,.025).peak);if(i===40&&mode!=='drums'){e.message({type:'pause'});const p=e.clock.beat;render(e,.1);assert.equal(e.clock.beat,p);e.message({type:'resume'});}}
  const ds=trace.filter(t=>t[0]==='drum').map(t=>t[1]);assert.ok(ds.length>8);for(let i=1;i<ds.length;i++)assert.ok(ds[i]>ds[i-1]);const expected=[];for(let bar=0;bar<=e.clock.tick/96;bar++)for(let slot=0;slot<16;slot++){const tick=bar*96+slot*6+(slot%2?.8*3.8:0);if(tick<e.clock.tick+e.clock.phase-1e-8)expected.push(tick);}assert.equal(ds.length,expected.length);assert.ok(ds.every((tick,i)=>Math.abs(tick-expected[i])<1e-9));
  if(mode!=='drums'&&mode!=='chord'){const arp=trace.filter(t=>t[0]==='arp').map(t=>t[1]);for(let i=1;i<arp.length;i++)assert.equal(arp[i]-arp[i-1],6);}assert.ok(peak<.881);e.message({type:'stop'});render(e,.5);assert.equal(e.voices.length,0);metrics.tempoSoak.push({sr,mode,tempoChanges:80,drumEvents:ds.length,peak});}
});
test('HAUNTED is a different dry harmonic instrument with bloom, detuning and reduced metal partials',()=>{
 metrics.haunted=[];for(const note of [36,60,84]){const data=[];for(const C of [old.Engine,Engine]){const e=make('haunted',{},C);e.note(note,.8,-1,'manual');render(e,.35);data.push(render(e,.5,true));}let dot=0,aa=0,bb=0;for(let i=0;i<data[0].data.length;i++){dot+=data[0].data[i]*data[1].data[i];aa+=data[0].data[i]**2;bb+=data[1].data[i]**2;}const correlation=dot/Math.sqrt(aa*bb);assert.ok(correlation<.95,JSON.stringify({note,correlation}));assert.ok(data[1].rms>.005&&data[1].peak<.5);metrics.haunted.push({note,oldRMS:data[0].rms,newRMS:data[1].rms,correlation});}
 const e=make('haunted');const v=e.note(60,.8,-1);render(e,.1);const early=v.bloom;render(e,1);assert.ok(v.bloom>early+.3);assert.notEqual(v.p,v.reedPhase);assert.match(worklet,/MODAL_WEIGHTS=\[\.06,\.055,\.018,\.006\]/);
});
test('HAUNTED dry staccato, sustained chords, long RELEASE and progression transitions stay finite and terminate',()=>{
 metrics.hauntedRelease=[];for(const release of [.03,1.5,4]){const e=make('haunted',{fx:{attack:.005,release,reverb:0,wooze:0,crush:0}});for(const n of [48,55,62,65])e.note(n,.75,-1,'manual');render(e,5);assert.ok(render(e,.1).rms>.008);e.release('manual');render(e,.5);const tail=render(e,.5);metrics.hauntedRelease.push({release,rms:tail.rms});render(e,8);assert.equal(e.voices.length,0);}assert.ok(metrics.hauntedRelease[2].rms>.001&&metrics.hauntedRelease[0].rms<1e-8);
 const e=make('haunted',{fx:{attack:.005,release:.03,reverb:0,wooze:0,crush:0}});for(let i=0;i<12;i++){e.note(48+i,.8,.05);assert.ok(render(e,.11).peak<.5);}render(e,.5);assert.equal(e.voices.length,0);
 e.configure({tempo:220,arp:{mode:'both',speed:5,length:.5}});e.message({type:'sequence',on:true});assert.ok(render(e,8).peak<.881);e.message({type:'stop'});render(e,.5);assert.equal(e.voices.length,0);
});
test('ROCKSTEADY changes only the requested default attack',()=>{
 const a=PRESETS.find(p=>p.id==='rocksteady'),b=old.PRESETS.find(p=>p.id==='rocksteady');assert.deepEqual({...a,attack:b.attack},b);assert.equal(a.attack,.05);for(const p of PRESETS.filter(p=>p.id!=='rocksteady'))assert.equal(p.attack,old.PRESETS.find(x=>x.id===p.id).attack);
});
test('DRIVE zero stays exact, is silent on zero input, and automated return to zero fully bypasses',()=>{
 const d=new DriveClass(48000);for(let i=0;i<2000;i++){const a=Math.sin(i*.81)*.4,b=Math.cos(i*.31)*.31,o=d.process(a,b,0);assert.equal(o[0],a);assert.equal(o[1],b);}const silence=new DriveClass(48000);for(let i=0;i<48000;i++)assert.deepEqual([...silence.process(0,0,1)],[0,0]);for(let i=0;i<48000;i++)d.process(.12,-.13,1);for(let i=0;i<48000;i++)d.process(.12,-.13,0);assert.equal(d.amount,0);assert.deepEqual([...d.process(.123,-.234,0)],[.123,-.234]);
});
test('DRIVE remains compensated on all instruments and produces repeatable high-setting sputter',()=>{
 metrics.drive=[];for(const p of PRESETS){const levels=[];for(const drive of [0,.2,.6,1]){const e=make(p.id,{drive});for(const n of [48,55,58,62,65,69])e.note(n,.8,-1,'manual');render(e,.4);const o=render(e,1);levels.push(o.rms);assert.ok(o.rms>1e-5&&o.peak<.881);}const changes=levels.map(x=>db(x,levels[0]));assert.ok(Math.max(...changes)<3);assert.ok(Math.min(...changes)>-8);metrics.drive.push({preset:p.id,relativeDB:changes});}
 const a=new DriveClass(48000),b=new DriveClass(48000),previous=new old.DriveClass(48000);let min=1,max=0,delta=0,last=0,diff=0;for(let i=0;i<144000;i++){const x=.15*Math.sin(2*Math.PI*220*i/48000),y=a.process(x,x,1)[0],z=b.process(x,x,1)[0];assert.equal(y,z);diff+=Math.abs(y-previous.process(x,x,1)[0]);delta=Math.max(delta,Math.abs(y-last));last=y;if(i>48000){min=Math.min(min,a.supply);max=Math.max(max,a.supply);}}assert.ok(max-min>.3);assert.ok(delta<.04);assert.ok(diff>100);metrics.driveSputter={minimumSupply:min,maximumSupply:max,maximumSampleDelta:delta,deterministic:true};
});
test('DRIVE retains antialiasing and improves upper-frequency definition versus V0.4.1',()=>{
 const n=8192,bin=736,sr=48000,a=.6,k=1+18*a*a,bias=.02+.4*a,d=new DriveClass(sr);d.amount=a;const filtered=new Float64Array(n),naive=new Float64Array(n);for(let i=0;i<n*8;i++){const x=.7*Math.sin(2*Math.PI*bin*i/n),o=d.process(x,x,a)[0];if(i>=n*7){filtered[i-n*7]=o;naive[i-n*7]=(Math.tanh(k*x+bias)-Math.tanh(bias))/k;}}
 function ratio(x){const p=fft(x);let alias=0,fund=0;for(let i=1;i<n/2;i++){if(Math.abs(i-bin)<=2)fund+=p[i];let legit=false;for(let h=1;h*bin<n/2;h++)if(Math.abs(i-h*bin)<=2)legit=true;if(!legit)alias+=p[i];}return alias/fund;}const reduction=10*Math.log10(ratio(naive)/ratio(filtered));assert.ok(reduction>12);const levels=[];for(const C of [old.DriveClass,DriveClass]){const f=new C(sr);let sum=0;for(let i=0;i<sr;i++){const x=.08*Math.sin(2*Math.PI*6000*i/sr),y=f.process(x,x,.6)[0];if(i>sr/2)sum+=y*y;}levels.push(Math.sqrt(sum/(sr/2)));}metrics.driveDefinition={aliasReductionDB:reduction,old6kRMS:levels[0],new6kRMS:levels[1]};assert.ok(levels[1]>=levels[0]*.98);
});
test('Fast CRUSH/DRIVE sweeps plus all engines remain bounded at 44.1 and 48 kHz and clear on STOP',()=>{
 metrics.stress=[];for(const sr of [44100,48000])for(const p of PRESETS){const e=make(p.id,{tempo:220,drive:1,drumVolume:.6,arp:{...defaultState().arp,mode:'both',speed:5,octaves:3},fx:{attack:.002,release:4,reverb:.7,wooze:.6,crush:1},glitch:.4,tone:.2},Engine,sr);e.message({type:'sequence',on:true});let peak=0;for(let i=0;i<12;i++){e.configure({tempo:i%2?220:40,drive:i%2,fx:{crush:i/11}});peak=Math.max(peak,render(e,.075).peak);}assert.ok(peak<.881);e.message({type:'stop'});render(e,.5);assert.equal(e.voices.length,0);assert.equal(e.strumPointers.size,0);assert.ok(render(e,.1).peak<1e-7);metrics.stress.push({sr,preset:p.id,peak});}
});
test('32-voice HAUNTED and DRIVE fit the desktop render budget; output routing and clock are untouched',()=>{
 metrics.cpu=[];for(const id of ['haunted','garage']){const e=make(id,{drive:1});for(let i=0;i<32;i++)e.note(42+i,.7,-1);render(e,.2);const start=performance.now();render(e,2);const ms=performance.now()-start;metrics.cpu.push({id,voices:32,drive:1,ms,realtimeFactor:2000/ms,physicalIPhone:false});assert.ok(ms<2000);}
 const prior=oldFile('worklet.js');
 // Monitoring adds counters around the unchanged stereo render call. Exact normal
 // output and diagnostic A/B/C behaviour are checked by dedicated numerical tests.
 assert.match(worklet,/this.engine.process\(o\[0\],o\[1\]\|\|o\[0\]\);/);
 const clock=s=>s.slice(s.indexOf('class MusicalClock'),s.indexOf('// WILMACHORD voice architectures')).split('// Four instrument-only')[0];assert.equal(clock(worklet),clock(prior));
});
test('KOSMISCHE controls the existing ring pulse with continuous phase, adjustable rate/depth and warmer filtering',()=>{
 const e=make('kosmische');render(e,.2);const before=e.pulsePhase;e.configure({kosmische:{pulseSpeed:.12,pulseDepth:1}});assert.equal(e.pulsePhase,before);render(e,1);assert.ok(Math.abs(e.pulseSpeedNow-.12)<1e-10);assert.ok(e.pulseDepthNow>.999);const phase=e.pulsePhase;render(e,1);assert.ok(Math.abs((e.pulsePhase-phase+1)%1-.12)<1e-6);
 e.configure({kosmische:{pulseSpeed:24,pulseDepth:0}});render(e,1);assert.ok(Math.abs(e.pulseSpeedNow-24)<1e-10);assert.ok(e.pulseDepthNow<1e-10);
 // Pulse depth changes only multiplication after the original moving resonant filter.
 const aa=make('kosmische',{kosmische:{pulseSpeed:2,pulseDepth:0}}),bb=make('kosmische',{kosmische:{pulseSpeed:2,pulseDepth:1}});for(const x of [aa,bb]){x.note(60,.7,-1);render(x,.8);}assert.equal(aa.voices[0].low,bb.voices[0].low);assert.equal(aa.voices[0].band,bb.voices[0].band);assert.match(worklet,/\.86\*\(700\+f\*2\.5/);metrics.kosmische={rateHz:[.12,24],depth:[0,1],phaseContinuous:true,filterCutoffScale:.86};
});
writeResults('sound-refinement',tests,metrics);
